input.command:
cd ~/measurement_env && menv python - <<'EOF'
import inspect, hera.analysis as a
for name in ['open_run','Run','summarize_run','plot_raw','fan_grids','resistance_grids','sdh_fft','sdh_onset','SdhOnset','SdhTone','field_invB','luttinger_frequency','GateCalibration']:
    obj = getattr(a, name)
    try:
        sig = str(inspect.signature(obj))
    except Exception:
        sig = ''
    doc = inspect.getdoc(obj) or ''
    print(f"===== {name}{sig}\n{doc[:1800]}\n")
    if name in ('Run','SdhOnset','SdhTone'):
        print('  members:', [m for m in dir(obj) if not m.startswith('_')])
EOF

